import{_ as i,o,c as l,a2 as a}from"./chunks/framework.DQbZ8cc1.js";const h=JSON.parse('{"title":"Google Login Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/installation/server/google-login.md","filePath":"en/docs/installation/server/google-login.md"}'),n={name:"en/docs/installation/server/google-login.md"};function t(s,e,c,r,d,g){return o(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="google-login-configuration" tabindex="-1">Google Login Configuration <a class="header-anchor" href="#google-login-configuration" aria-label="Permalink to “Google Login Configuration”">​</a></h1><p>This guide explains how to enable Google login in BBS-GO (including sign-in and account binding).</p><h2 id="_1-prerequisites" tabindex="-1">1. Prerequisites <a class="header-anchor" href="#_1-prerequisites" aria-label="Permalink to “1. Prerequisites”">​</a></h2><ul><li>Your site is reachable via public domain (production)</li><li>BBS-GO is installed and admin panel is accessible</li><li>A Google Cloud project is available</li></ul><h2 id="_2-create-oauth-credentials-in-google-cloud-console" tabindex="-1">2. Create OAuth Credentials in Google Cloud Console <a class="header-anchor" href="#_2-create-oauth-credentials-in-google-cloud-console" aria-label="Permalink to “2. Create OAuth Credentials in Google Cloud Console”">​</a></h2><ol><li>Open Google Cloud Console: <a href="https://console.cloud.google.com" target="_blank" rel="noreferrer">https://console.cloud.google.com</a></li><li>Go to <code>APIs &amp; Services</code> -&gt; <code>Credentials</code></li><li>Click <code>Create Credentials</code> -&gt; <code>OAuth client ID</code></li><li>Select application type <code>Web application</code></li><li>Configure origins and redirect URIs</li></ol><h3 id="_2-1-authorized-javascript-origins" tabindex="-1">2.1 Authorized JavaScript origins <a class="header-anchor" href="#_2-1-authorized-javascript-origins" aria-label="Permalink to “2.1 Authorized JavaScript origins”">​</a></h3><p>Add your site origins (examples):</p><ul><li><code>https://bbs.example.com</code></li><li>For local development: <code>http://localhost:8082</code></li></ul><h3 id="_2-2-authorized-redirect-uris" tabindex="-1">2.2 Authorized redirect URIs <a class="header-anchor" href="#_2-2-authorized-redirect-uris" aria-label="Permalink to “2.2 Authorized redirect URIs”">​</a></h3><p>You must add both callback URIs (replace with your domain):</p><ul><li><code>https://bbs.example.com/user/signin/callback/google</code></li><li><code>https://bbs.example.com/user/signin/callback/google_bind</code></li></ul><p>Local examples:</p><ul><li><code>http://localhost:8082/user/signin/callback/google</code></li><li><code>http://localhost:8082/user/signin/callback/google_bind</code></li></ul><p>After creation, copy:</p><ul><li><code>Client ID</code></li><li><code>Client Secret</code></li></ul><h2 id="_3-configure-in-bbs-go-admin" tabindex="-1">3. Configure in BBS-GO Admin <a class="header-anchor" href="#_3-configure-in-bbs-go-admin" aria-label="Permalink to “3. Configure in BBS-GO Admin”">​</a></h2><p>Open admin panel: <code>System Settings</code> -&gt; <code>Login Settings</code> -&gt; <code>Google Login</code></p><p>Fill and save:</p><ul><li><code>Enable</code>: ON</li><li><code>Client ID</code>: from Google Cloud Console</li><li><code>Client Secret</code>: from Google Cloud Console</li></ul><h2 id="_4-important-setting-baseurl" tabindex="-1">4. Important Setting (BaseURL) <a class="header-anchor" href="#_4-important-setting-baseurl" aria-label="Permalink to “4. Important Setting (BaseURL)”">​</a></h2><p>BBS-GO builds Google callback URLs using server config <code>baseURL</code> (shown as <code>BaseURL</code> in some sample files).</p><p>Make sure <code>bbs-go.yaml</code> uses your full site URL, for example:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">baseURL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://bbs.example.com</span></span></code></pre></div><p>If it remains <code>/</code>, callback URL may be non-absolute and Google login can fail.</p><h2 id="_5-verification" tabindex="-1">5. Verification <a class="header-anchor" href="#_5-verification" aria-label="Permalink to “5. Verification”">​</a></h2><ol><li>Open sign-in page: <code>/user/signin</code></li><li>Confirm Google login button is visible</li><li>Click it and verify redirect to Google authorization page</li><li>After consent, user should return and sign in successfully</li></ol><p>Bind-flow verification:</p><ol><li>Sign in and open account binding page</li><li>Start Google binding</li><li>After consent, account should show as bound</li></ol><h2 id="_6-common-issues" tabindex="-1">6. Common Issues <a class="header-anchor" href="#_6-common-issues" aria-label="Permalink to “6. Common Issues”">​</a></h2><h3 id="redirect-uri-mismatch" tabindex="-1">redirect_uri_mismatch <a class="header-anchor" href="#redirect-uri-mismatch" aria-label="Permalink to “redirect_uri_mismatch”">​</a></h3><p>Cause: Callback URI in Google Console does not match actual callback URI.</p><p>Fix:</p><ul><li>Verify <code>Authorized redirect URIs</code></li><li>Verify <code>baseURL</code> in <code>bbs-go.yaml</code></li><li>Check scheme/port consistency (<code>http</code> vs <code>https</code>, custom port)</li></ul><h3 id="google-login-is-not-enabled" tabindex="-1">&quot;Google login is not enabled&quot; <a class="header-anchor" href="#google-login-is-not-enabled" aria-label="Permalink to “&quot;Google login is not enabled&quot;”">​</a></h3><p>Cause: Google login switch is disabled in admin settings.</p><p>Fix:</p><ul><li>Enable <code>Google Login</code> in <code>System Settings -&gt; Login Settings</code></li><li>Ensure <code>Client ID</code> and <code>Client Secret</code> are saved</li></ul><h3 id="works-locally-but-fails-in-production" tabindex="-1">Works locally but fails in production <a class="header-anchor" href="#works-locally-but-fails-in-production" aria-label="Permalink to “Works locally but fails in production”">​</a></h3><p>Usually domain/protocol/port mismatch.</p><p>Fix:</p><ul><li>Add production domain to <code>Authorized JavaScript origins</code></li><li>Add production callback URIs to <code>Authorized redirect URIs</code></li><li>Ensure <code>baseURL</code> matches production domain exactly</li></ul>',42)])])}const p=i(n,[["render",t]]);export{h as __pageData,p as default};
